"""Dark styling applied to every in-app dialog and wizard."""
DARK_DIALOG_STYLESHEET = "QDialog,QWizard,QWizardPage{background-color:#1e1e1e;color:#e6e6e6;font-family:'Segoe UI';}\nQDialog QWidget,QWizard QWidget,QWizardPage QWidget{background-color:#1e1e1e;color:#e6e6e6;}\nQDialog QLabel,QWizard QLabel,QWizardPage QLabel{color:#e6e6e6;background-color:transparent;}\nQDialog QLineEdit,QDialog QTextEdit,QDialog QPlainTextEdit,QDialog QComboBox,QDialog QSpinBox,QDialog QDateEdit,QDialog QTimeEdit,QDialog QDateTimeEdit,QDialog QAbstractSpinBox,QWizard QLineEdit,QWizard QComboBox{background-color:#252526;color:#f1f1f1;border:1px solid #555;padding:3px 5px;selection-background-color:#094771;selection-color:#ffffff;}\nQDialog QLineEdit:read-only{background-color:#222223;color:#c8c8c8;}\nQDialog QComboBox QAbstractItemView{background-color:#252526;color:#f1f1f1;selection-background-color:#094771;selection-color:#ffffff;border:1px solid #555;}\nQDialog QPushButton,QDialog QToolButton,QWizard QPushButton{background-color:#333337;color:#e6e6e6;border:1px solid #555;border-radius:3px;padding:3px 9px;min-height:20px;}\nQDialog QPushButton:hover,QDialog QToolButton:hover,QWizard QPushButton:hover{background-color:#3a3a40;border-color:#1688d4;}\nQDialog QPushButton:pressed,QDialog QToolButton:pressed,QWizard QPushButton:pressed{background-color:#252526;}\nQDialog QPushButton:default,QWizard QPushButton:default{border:1px solid #1688d4;}\nQDialog QPushButton:disabled,QDialog QToolButton:disabled,QWizard QPushButton:disabled{background-color:#29292b;color:#858585;border-color:#3e3e42;}\nQDialog QCheckBox,QDialog QRadioButton,QWizard QCheckBox,QWizard QRadioButton{color:#e6e6e6;background:transparent;spacing:5px;}\nQDialog QTableWidget,QDialog QTreeWidget,QDialog QListWidget,QDialog QTableView,QDialog QTreeView,QDialog QListView{background-color:#252526;color:#e6e6e6;border:1px solid #4b4b4b;alternate-background-color:#2d2d30;gridline-color:#414141;selection-background-color:#094771;selection-color:#ffffff;}\nQDialog QHeaderView::section{background-color:#333337;color:#e6e6e6;border:0;border-right:1px solid #4b4b4b;border-bottom:1px solid #555;padding:3px 5px;}\nQDialog QTabWidget::pane{background-color:#1e1e1e;border:1px solid #4b4b4b;}\nQDialog QTabBar::tab{background-color:#2d2d30;color:#cfcfcf;border:1px solid #4b4b4b;padding:4px 8px;}\nQDialog QTabBar::tab:selected{background-color:#1e1e1e;color:#ffffff;border-bottom-color:#1e1e1e;}\nQDialog QStackedWidget{background-color:#1e1e1e;color:#e6e6e6;}\nQDialog QGroupBox{background-color:#1e1e1e;color:#e6e6e6;border:1px solid #4b4b4b;margin-top:7px;padding-top:5px;}\nQDialog QProgressBar{background-color:#2d2d30;color:#e6e6e6;border:1px solid #555;text-align:center;}\nQDialog QProgressBar::chunk{background-color:#1688d4;}\nQDialog QScrollArea,QDialog QScrollArea QWidget{background-color:#1e1e1e;color:#e6e6e6;}\nQDialog QMenu{background-color:#252526;color:#e6e6e6;border:1px solid #4b4b4b;}\nQDialog QMenu::item:selected{background-color:#094771;color:#ffffff;}\nQDialog QScrollBar:vertical{background-color:#252526;width:12px;margin:0;}\nQDialog QScrollBar::handle:vertical{background-color:#555;min-height:24px;border-radius:5px;}\nQDialog QScrollBar:horizontal{background-color:#252526;height:12px;margin:0;}\nQDialog QScrollBar::handle:horizontal{background-color:#555;min-width:24px;border-radius:5px;}\nQToolTip{background-color:#252526;color:#f1f1f1;border:1px solid #555;padding:3px;}\n"


def apply_dark_dialog_theme(app):
    app.setStyleSheet(DARK_DIALOG_STYLESHEET)
